UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Stable Patient — Size Assessment","body":"Obtain **CXR or CT** to assess pneumothorax size, but **2024 ERS/EACTS/ESTS + BTS 2023 emphasize symptom-based, not size-based, decisions.** [6]\n\nPOCUS lung point location provides initial size estimate.\n\n**Updated paradigm (2024):**\n• Asymptomatic / minimally symptomatic PSP → conservative management regardless of size (Brown et al NEJM 2020 conservative-non-inferior trial)\n• Symptomatic → needle aspiration preferred over chest tube as first invasive step","citation":[1,5,6],"options":[{"label":"Asymptomatic / minimally symptomatic","description":"2024 ERS/EACTS/ESTS: conservative management first-line regardless of size","next":"small-ptx"},{"label":"Symptomatic PSP (pain, dyspnea)","description":"Needle aspiration preferred over chest tube per 2024 ERS","next":"large-ptx"}],"images":[{"src":"images/pneumothorax/ptx-cxr-annotated.png","alt":"Annotated chest X-ray showing pneumothorax","caption":"CXR: visceral pleural line (white arrow) with absent lung markings lateral to it. Size historically measured at apex (BTS); 2024 guidelines now prioritize symptoms over absolute size."}],"summary":"2024 ERS/EACTS/ESTS + BTS 2023 — symptom-based, not size-based; conservative for asymptomatic PSP, needle aspiration before chest tube for symptomatic"}'::jsonb
WHERE id = 'stable-ptx-management' AND tree_id = 'pneumothorax';

-- Node: small-ptx (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Asymptomatic / Minimally Symptomatic PSP — Conservative Management","body":"**2024 ERS/EACTS/ESTS + BTS 2023:** Conservative (watch-and-wait) management is first-line for asymptomatic or minimally symptomatic primary spontaneous pneumothorax (PSP), **regardless of size**. [6]\n\n**Evidence:** Brown et al (NEJM 2020 PSP-CMT trial): conservative care non-inferior to chest drain for 8-week radiologic resolution, with fewer adverse events and lower 1-year recurrence. Pooled meta-analysis (11,922 cases, 8 studies): RR of recurrence 0.98 (95% CI 0.75-1.28).\n\n**ED disposition options:**\n• Observation 4-6 hours, repeat CXR — if stable, discharge with close follow-up (48-72h)\n• Ambulatory management (Heimlich valve) if local infrastructure supports it\n• Supplemental O2 increases reabsorption rate (~2%/day → ~4%/day) but is not mandatory in modern conservative protocols\n\n**Discharge criteria:**\n• Stable on repeat imaging at 4-6h\n• No respiratory distress\n• Reliable follow-up within 48-72h\n• Patient understands return precautions (worsening dyspnea, chest pain)\n\n**Admission for observation** still appropriate for: secondary spontaneous PTX (SSP — underlying lung disease), uncertain follow-up, large symptomatic PSP awaiting intervention.","citation":[1,6],"confidence":"recommended"}'::jsonb
WHERE id = 'small-ptx' AND tree_id = 'pneumothorax';

-- Node: large-ptx (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Symptomatic PSP — Intervention","body":"**2024 ERS/EACTS/ESTS strong recommendation:** Needle aspiration is **preferred over chest tube** as the first invasive intervention for symptomatic PSP. [6]\n\n**Step 1 — Needle Aspiration:**\n• 16-18G angiocath or aspiration kit, 2nd ICS MCL\n• Aspirate up to 2.5 L; stop if resistance, cough, or 2.5 L reached\n• Reassess with CXR — if lung re-expanded: observe, then discharge with close follow-up\n• Success rate ~60-70% for PSP\n\n**Step 2 — Chest Drain (if aspiration fails or SSP):**\n• **Small-bore pigtail catheter (<14 Fr) preferred for PSP** (2010 BTS, retained in 2023)\n• Large-bore (>28 Fr) reserved for SSP with hemothorax, large air leak, or mechanical ventilation\n• Connect to underwater seal ± suction\n\n**Ambulatory device (Heimlich/Atrium Pneumostat):** Increasingly favored for select PSP patients with good support and access to follow-up.\n\nSee [Chest Tube / Pneumothorax Management](#/tree/chest-tube) for tube thoracostomy procedure.","citation":[1,6],"confidence":"recommended"}'::jsonb
WHERE id = 'large-ptx' AND tree_id = 'pneumothorax';

