-- Node: pdp-norepi-peripheral (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Peripheral Norepinephrine - Safety Evidence","body":"**2024-2025 Evidence supports peripheral norepinephrine:** [8][9][12]\n\n**Cleveland Clinic Prospective Study (CHEST 2024):**\n- Implementing peripheral NE protocol avoided 1 CVC day per patient\n- 51.6% of patients never required central line insertion\n- Safe, feasible, and associated with decreased CVC utilization\n\n**2025 Follow-up data:**\n- Multiple cohorts now support peripheral NE for **24-48 hours** (mean time to adverse event 55.9h in systematic review)\n- Extravasation occurs primarily in the first 24 hours\n- Concentration matters: 16-32 mcg/mL is safer than higher concentrations\n- Supports SSC guideline that vasopressors should start peripherally rather than delaying for central access\n\n**Systematic Review (2025):**\n- 83 articles reviewed\n- Noradrenaline CAN be administered peripherally\n- Complications (thrombophlebitis, cellulitis, tissue necrosis) are possible but incidence is LOW\n- Phentolamine is first-line for extravasation\n\n**Practical guidance:**\n- Use large-bore IV in proximal location (antecubital preferred)\n- Monitor IV site every 1-2 hours\n- Have phentolamine ready (5-10 mg diluted in 10 mL NS for local infiltration)\n- Transition to central line when stable and practical","citation":[8,9,12],"next":"pdp-troubleshoot","summary":"Peripheral NE safe up to 48h per 2024-25 data — 51.6% never needed central line, use large-bore proximal IV, have phentolamine ready","skippable":true}'::jsonb
WHERE id = 'pdp-norepi-peripheral' AND tree_id = 'push-dose-pressors';

-- Node: sah-bp-control (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Blood Pressure Management","body":"**Target: SBP <160 mmHg** until aneurysm is secured (AHA/ASA 2023 — no precise numeric target mandated, but avoiding hypertension minimizes rebleeding).\n\nHigher pressures may increase rebleeding risk, but aggressive lowering may compromise cerebral perfusion.\n\n**Titratable IV agents:**\n• [Labetalol](#/drug/labetalol/sah blood pressure) — 10-20 mg IV bolus over 1-2 min. Repeat or start infusion 2-8 mg/min. Max 300 mg/24h.\n• [Nicardipine](#/drug/nicardipine/sah blood pressure) — 5 mg/hr IV, titrate by 2.5 mg/hr q5-15 min. Max 15 mg/hr.\n• [Clevidipine](#/drug/clevidipine/sah blood pressure) — 1-2 mg/hr IV, double q90 sec to target. Ultra-short t½ (~1 min).\n\n**Avoid nitroprusside** — increases intracranial pressure and risk of toxicity with prolonged infusion.\n\n**Arterial line** recommended for continuous BP monitoring if extended ED stay anticipated.","citation":[2,3],"next":"sah-vasospasm-prev","treatment":{"firstLine":{"drug":"Labetalol","dose":"10-20 mg IV bolus, then 2-8 mg/min infusion","route":"IV","frequency":"Bolus over 1-2 min, repeat PRN or continuous infusion","duration":"Until SBP <160 mmHg sustained","notes":"Max 300 mg/24h. Avoid in bradycardia, heart block, severe asthma."},"alternative":{"drug":"Nicardipine","dose":"5 mg/hr, titrate by 2.5 mg/hr q5-15 min","route":"IV infusion","frequency":"Continuous","duration":"Until SBP <160 mmHg sustained","notes":"Max 15 mg/hr. Preferred if beta-blocker contraindicated. Clevidipine (1-2 mg/hr, double q90 sec) is an alternative with ultra-short half-life."},"monitoring":"Arterial line for continuous BP monitoring. Target SBP <160 mmHg. Avoid nitroprusside (increases ICP)."},"summary":"Target SBP <160 until aneurysm secured — labetalol or nicardipine IV, avoid nitroprusside (increases ICP), arterial line recommended","safetyLevel":"critical"}'::jsonb
WHERE id = 'sah-bp-control' AND tree_id = 'sah';

-- Node: sah-rebleed-prev (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Rebleeding Prevention","body":"Rebleeding is **one of the most devastating complications** after aSAH, with the highest mortality of any complication.\n\n• Cumulative incidence: **8-23%** in first 72 hours\n• **50-90% of episodes occur within first 6 hours** after primary bleed\n• Clinical signs: acute/worsening headache, decreased consciousness, loss of brainstem reflexes, posturing, respiratory arrest, seizures\n\n**Risk factors for rebleeding:**\n• High-grade SAH (Hunt & Hess 4-5)\n• Larger aneurysms\n• Prolonged time to surgery\n• Sentinel/warning bleeds\n• Catheter angiography\n\n**Prevention strategies:**\n• **Early definitive repair** — primary strategy (within 24-72 hours per 2023 AHA/ASA)\n• **Blood pressure control** — SBP <160 mmHg\n• **Antifibrinolytics (TXA): NOT recommended** by 2023 AHA/ASA. The ULTRA trial (Post 2021, Lancet) showed ultra-early short-course TXA did not improve 6-month functional outcomes (mRS 0-3: 60% TXA vs 64% control) and the rate of excellent outcome (mRS 0-2) was *lower* in the TXA arm. Increased hydrocephalus (pooled +13%) and seizures (17% vs 10%, OR 1.95) signals — risks outweigh the modest rebleed reduction. [16]\n\n**Rapid diagnosis + early repair** remains the optimal approach.","citation":[2,14,16],"next":"sah-cardiac-comp","summary":"Rebleeding 8-23% in first 72h (50-90% within 6h) — highest mortality of any SAH complication, early repair is primary prevention. TXA NOT recommended per 2023 AHA/ASA (ULTRA trial negative).","safetyLevel":"critical"}'::jsonb
WHERE id = 'sah-rebleed-prev' AND tree_id = 'sah';

